import {scientificCalculate} from './scientific-core.mjs';
// Public calculation helper uses degrees, like the scientific calculator interface.
export const calculate=(expression,options)=>scientificCalculate(expression,options);
export const ieltsOverall = values => Math.round(values.reduce((a,b)=>a+b,0)/4*2)/2;
