export const rawBand=(score,type)=>({listening,academic,general}[type]||academic).find(([min])=>score>=min)[1];
export function loan(principal,annual,months){const r=annual/1200,payment=r===0?principal/months:principal*r/(1-Math.pow(1+r,-months));return{payment,total:payment*months,interest:payment*months-principal};}
export function compound(principal,annual,years,monthly=0,frequency=12){const r=annual/100,base=1+r/frequency,growth=base**(frequency*years);const effective=(1+r/frequency)**(frequency/12)-1;const contributions=effective===0?monthly*years*12:monthly*((1+effective)**(years*12)-1)/effective;const total=principal*growth+contributions;return{total,invested:principal+monthly*12*years,interest:total-principal-monthly*12*years};}
export function dateUTC(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))throw Error('Choose a valid date.');const d=new Date(value+'T00:00:00Z');if(!Number.isFinite(+d)||d.toISOString().slice(0,10)!==value)throw Error('Choose a valid date.');return d;}
export function age(birth,asof){const b=dateUTC(birth),a=dateUTC(asof);if(a<b)throw Error('The comparison date must be after the birth date.');let totalMonths=(a.getUTCFullYear()-b.getUTCFullYear())*12+a.getUTCMonth()-b.getUTCMonth();const shifted=m=>{const d=new Date(Date.UTC(b.getUTCFullYear(),b.getUTCMonth()+m,1));d.setUTCDate(Math.min(b.getUTCDate(),new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));return d;};if(shifted(totalMonths)>a)totalMonths--;return{years:Math.floor(totalMonths/12),months:totalMonths%12,days:Math.round((a-shifted(totalMonths))/86400000),totalDays:Math.round((a-b)/86400000)};}
export const units={length:{'Meters':1,'Kilometers':1000,'Centimeters':.01,'Millimeters':.001,'Miles':1609.344,'Yards':.9144,'Feet':.3048,'Inches':.0254},weight:{'Kilograms':1,'Grams':.001,'Milligrams':.000001,'Pounds':.45359237,'Ounces':.028349523125},area:{'Square meters':1,'Square feet':.09290304,'Acres':4046.8564224,'Hectares':10000,'Ropani':508.737047,'Aana':31.7960654,'Bigha (Terai)':6772.63,'Kattha (Terai)':338.6315},volume:{'Liters':1,'Milliliters':.001,'US gallons':3.785411784,'US cups':.2365882365,'Cubic meters':1000},data:{'Bytes':1,'KB (1000 B)':1000,'MB (1000 KB)':1e6,'GB (1000 MB)':1e9,'KiB (1024 B)':1024,'MiB (1024 KiB)':1048576,'GiB (1024 MiB)':1073741824},temperature:{'Celsius':1,'Fahrenheit':1,'Kelvin':1}};
export function convertUnit(n,group,from,to){if(group==='temperature'){let c=from==='Celsius'?n:from==='Fahrenheit'?(n-32)*5/9:n-273.15;if(c< -273.15-1e-9)throw Error('Temperature is below absolute zero.');return to==='Celsius'?c:to==='Fahrenheit'?c*9/5+32:c+273.15;}return n*units[group][from]/units[group][to];}
export function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b)[a,b]=[b,a%b];return a;}
export function secureIndex(max){if(!Number.isSafeInteger(max)||max<=0||max>4294967296)throw Error('Invalid random range.');const bound=Math.floor(4294967296/max)*max,b=new Uint32Array(1);do{crypto.getRandomValues(b);}while(b[0]>=bound);return b[0]%max;}
export function password(length,sets){if(!sets.length)throw Error('Choose at least one character group.');const all=sets.join(''),chars=sets.map(s=>s[secureIndex(s.length)]);while(chars.length<length)chars.push(all[secureIndex(all.length)]);for(let i=chars.length-1;i>0;i--){let j=secureIndex(i+1);[chars[i],chars[j]]=[chars[j],chars[i]];}return chars.join('');}
export const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const formatNumber=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:8});
